css:
[data-bz-section="location-faq"] .bz-block { padding-block: 0 }
[data-bz-section="location-faq"] .bz-block + .bz-block { padding-block-start: 0 }
[data-bz-section="location-faq"] .bz-row + .bz-row { margin-top: 0 }
/* Handoff FAQ band: a 900px well (gutter included), 90px of band above and below, the list at the well's full width. */
.bz-sharedsection[data-bz-section="location-faq"] > .bz-section { padding-block: 90px }
.bz-sharedsection[data-bz-section="location-faq"] > .bz-section > .bz-container { max-width: 900px }
[data-bz-section="location-faq"] .bz-col { grid-column: 1 / -1 }
.bz-sharedsection[data-bz-section="location-faq"] .bz-block h2 { font-size: 34px; line-height: 1.7; margin: 0 0 40px }
[data-bz-section="location-faq"] .bz-eyebrow { margin-bottom: 18px }
@media (max-width: 640px) { .bz-sharedsection[data-bz-section="location-faq"] > .bz-section { padding-block: 64px } .bz-sharedsection[data-bz-section="location-faq"] .bz-block h2 { font-size: 26px } }
.bz-sharedsection[data-bz-section="location-faq"] .bz-faq > summary { line-height: 22px }

js:
// The handoff opens the first answer. The faq widget draws native <details>, all closed; open the first
// one once, on the published page only. Every answer stays reachable without this.
document.querySelectorAll('[data-bz-section="location-faq"]').forEach(function (band) {
  var first = band.querySelector('details.bz-faq');
  if (first && !band.querySelector('details.bz-faq[open]')) first.open = true;
});
